import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.BpFM782D.js";const q=JSON.parse('{"title":"qa-team","description":"","frontmatter":{},"headers":[],"relativePath":"commands/ecc-qa-team.md","filePath":"commands/ecc-qa-team.md"}'),o={name:"commands/ecc-qa-team.md"};function l(i,t,h,c,n,s){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="qa-team" tabindex="-1">qa-team <a class="header-anchor" href="#qa-team" aria-label="Permalink to &quot;qa-team&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>qa-team</td></tr><tr><td>說明</td><td>派出 agent 團隊進行部署前品質審查（實驗性功能）。</td></tr><tr><td>系列</td><td>ECC</td></tr><tr><td>來源檔案</td><td><code>commands/qa-team.md</code></td></tr></tbody></table><hr><p>你是部署前品質保證 agent 團隊的 team lead。你的工作是派出隊友、協調他們的工作，並綜合出 go/no-go 報告。你不自己進行審查 — 你只負責委派和綜合。</p><p><strong>輸入</strong>：<code>/qa-team</code> 加上可選的目標 URL。範例：</p><ul><li><code>/qa-team</code> — 審查目前未提交的變更</li><li><code>/qa-team https://example.com</code> — 審查已部署的網站</li></ul><h2 id="步驟-1-偵察" tabindex="-1">步驟 1：偵察 <a class="header-anchor" href="#步驟-1-偵察" aria-label="Permalink to &quot;步驟 1：偵察&quot;">​</a></h2><ol><li>執行 <code>git diff --stat</code> 查看變更的檔案</li><li>識別變更的類別（前端、後端、設定檔、測試等）</li><li>決定需要哪些審查者</li></ol><h2 id="步驟-2-派出隊友" tabindex="-1">步驟 2：派出隊友 <a class="header-anchor" href="#步驟-2-派出隊友" aria-label="Permalink to &quot;步驟 2：派出隊友&quot;">​</a></h2><p>根據變更類別，使用 Agent 工具平行派出 2-4 個專業審查者。每個隊友收到：</p><ul><li>要審查的具體檔案</li><li>他們的專業重點</li><li>嚴重度標記規則（high/med/low）</li></ul><h3 id="可用的審查者角色" tabindex="-1">可用的審查者角色： <a class="header-anchor" href="#可用的審查者角色" aria-label="Permalink to &quot;可用的審查者角色：&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>專注於</th><th>使用時機</th></tr></thead><tbody><tr><td>security-reviewer</td><td>OWASP、密鑰、注入</td><td>總是使用</td></tr><tr><td>code-quality</td><td>命名、結構、重複</td><td>總是使用</td></tr><tr><td>test-coverage</td><td>測試缺口、邊界案例</td><td>有測試檔案時</td></tr><tr><td>a11y-reviewer</td><td>無障礙、ARIA、鍵盤導航</td><td>有 UI 變更時</td></tr><tr><td>perf-reviewer</td><td>效能、bundle 大小、N+1</td><td>有資料擷取/渲染變更時</td></tr></tbody></table><h2 id="步驟-3-綜合報告" tabindex="-1">步驟 3：綜合報告 <a class="header-anchor" href="#步驟-3-綜合報告" aria-label="Permalink to &quot;步驟 3：綜合報告&quot;">​</a></h2><p>收集所有隊友的回報後，按照 QA Report 規範產出報告：</p><ol><li>寫入 <code>docs/qa-reports/qa-report-{YYYY-MM-DD}-{short-hash}.md</code></li><li>複製一份為 <code>docs/qa-reports/qa-report-latest.md</code></li><li>依據決策標準做出 go/no-go 判定</li></ol><h2 id="決策標準" tabindex="-1">決策標準 <a class="header-anchor" href="#決策標準" aria-label="Permalink to &quot;決策標準&quot;">​</a></h2><table tabindex="0"><thead><tr><th>條件</th><th>決策</th></tr></thead><tbody><tr><td>有任何 high</td><td><strong>NO-GO</strong></td></tr><tr><td>只有 med</td><td><strong>CONDITIONAL-GO</strong>（列出必修項目）</td></tr><tr><td>全部 low 或無問題</td><td><strong>GO</strong></td></tr></tbody></table>',18)])])}const b=a(o,[["render",l]]);export{q as __pageData,b as default};
